from abc import ABC, abstractmethod
from typing import Any


class DataProcessor(ABC):
    """Template Method: defines the processing algorithm skeleton."""

    def process(self, data: list[Any]) -> list[Any]:
        result: list[Any] = []
        for item in data:
            if not self.filter(item):
                continue
            result.append(self.transform(item))
        return result

    def filter(self, item: Any) -> bool:
        """Hook: return True to include item. Default accepts all."""
        return True

    @abstractmethod
    def transform(self, item: Any) -> Any:
        """Hook: transform item. Subclasses must implement."""
        ...


class ConfigDataProcessor(DataProcessor):
    """Concrete processor that accepts filter/transform callables via config dict."""

    def __init__(self, config: dict[str, Any]) -> None:
        self.config = config

    def filter(self, item: Any) -> bool:
        if self.config.get('filter'):
            return self.config['filter'](item)
        return True

    def transform(self, item: Any) -> Any:
        if self.config.get('transform'):
            return self.config['transform'](item)
        return item


class DataProcessorProxy(DataProcessor):
    """Proxy with caching and authorization — delegates to a real processor."""

    def __init__(self, processor: DataProcessor, authorized: bool = True) -> None:
        self._processor = processor
        self._authorized = authorized
        self._cache: list[Any] | None = None
        self._cached_data_id: int | None = None

    def process(self, data: list[Any]) -> list[Any]:
        if not self._authorized:
            raise PermissionError("Not authorized to process data")

        data_id = id(data)
        if self._cached_data_id == data_id and self._cache is not None:
            return self._cache

        result = self._processor.process(data)
        self._cache = result
        self._cached_data_id = data_id
        return result

    def filter(self, item: Any) -> bool:
        return self._processor.filter(item)

    def transform(self, item: Any) -> Any:
        return self._processor.transform(item)

